import{_ as a,o as l,c as i,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"2023Q3 Ceph社区季度总结","description":"","frontmatter":{"title":"2023Q3 Ceph社区季度总结","date":"2023-9-01","tags":["Ceph","社区动态","技术发展"],"outline":"deep"},"headers":[],"relativePath":"quarterly/2023Q3_Ceph社区季度总结.md","filePath":"quarterly/2023Q3_Ceph社区季度总结.md","lastUpdated":1780459816000}'),t={name:"quarterly/2023Q3_Ceph社区季度总结.md"};function o(h,e,n,c,d,u){return l(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="ceph-社区-2023-年第三季度总结报告" tabindex="-1">Ceph 社区 2023 年第三季度总结报告 <a class="header-anchor" href="#ceph-社区-2023-年第三季度总结报告" aria-label="Permalink to &quot;Ceph 社区 2023 年第三季度总结报告&quot;">​</a></h1><h2 id="_1-本季度-ceph-社区的主要活动和重点议题" tabindex="-1">1. 本季度 Ceph 社区的主要活动和重点议题 <a class="header-anchor" href="#_1-本季度-ceph-社区的主要活动和重点议题" aria-label="Permalink to &quot;1. 本季度 Ceph 社区的主要活动和重点议题&quot;">​</a></h2><h3 id="_1-1-病理学-pathology-项目的改进与实施" tabindex="-1">1.1 病理学（Pathology）项目的改进与实施 <a class="header-anchor" href="#_1-1-病理学-pathology-项目的改进与实施" aria-label="Permalink to &quot;1.1 病理学（Pathology）项目的改进与实施&quot;">​</a></h3><ul><li>Devansh，Google Summer of Code 实习生，SEF 项目成员，介绍了病理学项目的改进和实施情况。</li><li>项目旨在改进病理学测试框架，使其更易于使用，并通过仪表板提供更直观的测试体验。</li><li>下一代 Pulpito 的开发，实现 GitHub 认证、作业调度和作业终止功能。</li></ul><h3 id="_1-2-ceph-rgw-重构会议" tabindex="-1">1.2 Ceph RGW 重构会议 <a class="header-anchor" href="#_1-2-ceph-rgw-重构会议" aria-label="Permalink to &quot;1.2 Ceph RGW 重构会议&quot;">​</a></h3><ul><li>会议主要讨论了 Ceph RGW 的重构计划，包括 Reef 版本更新、异步请求重构、线程池优化以及从 librados 迁移到 Neo-rados 的计划。</li><li>决定解决版本化对象一致性和加密对象损坏问题，以避免功能退化。</li><li>讨论了异步请求的正确性和防止新增阻塞调用。</li><li>计划降低线程池大小，并进行性能测试以确定最佳大小。</li><li>逐步从 librados 迁移到 Neo-rados。</li></ul><h3 id="_1-3-ceph-开发者会议-cds-squid-rados" tabindex="-1">1.3 Ceph 开发者会议：CDS Squid: RADOS <a class="header-anchor" href="#_1-3-ceph-开发者会议-cds-squid-rados" aria-label="Permalink to &quot;1.3 Ceph 开发者会议：CDS Squid: RADOS&quot;">​</a></h3><ul><li>会议讨论了 Ceph MGR 的相关议题，包括性能问题、编码解码的可测试性、客户端之间的 QoS、读取均衡器、可用性跟踪、Erasure 编码配置文件的简化等。</li><li>将继续推进 Op Tracker 在 MGR 中的集成工作。</li><li>改进编码解码框架的测试覆盖率，并强制注册新的可编码类。</li><li>继续开发客户端之间的 QoS 功能，并解决相关的技术挑战。</li><li>开发自动运行的读取均衡器，并探索不同的触发机制。</li></ul><h2 id="_2-技术发展和创新亮点" tabindex="-1">2. 技术发展和创新亮点 <a class="header-anchor" href="#_2-技术发展和创新亮点" aria-label="Permalink to &quot;2. 技术发展和创新亮点&quot;">​</a></h2><h3 id="_2-1-ceph-blue-store-会议" tabindex="-1">2.1 Ceph Blue Store 会议 <a class="header-anchor" href="#_2-1-ceph-blue-store-会议" aria-label="Permalink to &quot;2.1 Ceph Blue Store 会议&quot;">​</a></h3><ul><li>讨论了 Ceph Blue Store 的多个关键议题，包括分配器模拟器、碎片化处理、弹性共享 Blob、Codel 算法、自定义写前锁等。</li><li>将继续推进分配器模拟器的开发，并完善其度量标准。</li><li>在 Blue Store 中实现碎片整理的基本原语。</li><li>弹性共享 Blob 特性将继续在不同版本中进行测试和部署。</li><li>完善 Codel 算法和自定义写前锁的实现。</li></ul><h3 id="_2-2-ceph-code-walkthroughs-seastore" tabindex="-1">2.2 Ceph Code Walkthroughs: SeaStore <a class="header-anchor" href="#_2-2-ceph-code-walkthroughs-seastore" aria-label="Permalink to &quot;2.2 Ceph Code Walkthroughs: SeaStore&quot;">​</a></h3><ul><li>SeaStore 是一个新的对象存储实现，专为 Crimson 的线程和回调模型设计。</li><li>目标是避免 CPU 密集型的元数据设计，如 roxdb，并提供灵活的架构以支持多种存储配置和工作负载。</li><li>SeaStore 将支持多种存储配置，包括 QLC 或 ZNS 闪存设备、硬盘以及高性能的 NVMe 设备。</li></ul><h2 id="_3-重要的决策和里程碑" tabindex="-1">3. 重要的决策和里程碑 <a class="header-anchor" href="#_3-重要的决策和里程碑" aria-label="Permalink to &quot;3. 重要的决策和里程碑&quot;">​</a></h2><h3 id="_3-1-ceph-rgw-refactoring-meeting-2023-06-14" tabindex="-1">3.1 Ceph RGW Refactoring Meeting 2023-06-14 <a class="header-anchor" href="#_3-1-ceph-rgw-refactoring-meeting-2023-06-14" aria-label="Permalink to &quot;3.1 Ceph RGW Refactoring Meeting 2023-06-14&quot;">​</a></h3><ul><li>决定通过分片策略来解决存储桶数量增长的问题。</li><li>讨论了是否需要为存储桶列表 API 增加排序和分页功能。</li></ul><h3 id="_3-2-ceph-orchestrator-meeting-2023-08-29" tabindex="-1">3.2 Ceph Orchestrator Meeting 2023-08-29 <a class="header-anchor" href="#_3-2-ceph-orchestrator-meeting-2023-08-29" aria-label="Permalink to &quot;3.2 Ceph Orchestrator Meeting 2023-08-29&quot;">​</a></h3><ul><li>决定暂时保留现有的命名 <code>cephadm</code>。</li><li>决定采用 Python Black 作为代码格式化工具，并计划将其纳入 CI 流程。</li></ul><h2 id="_4-社区贡献和合作情况" tabindex="-1">4. 社区贡献和合作情况 <a class="header-anchor" href="#_4-社区贡献和合作情况" aria-label="Permalink to &quot;4. 社区贡献和合作情况&quot;">​</a></h2><ul><li>本季度，Ceph 社区活跃度高，许多贡献者和开发者参与了社区活动，包括提交代码、修复 Bug、参与讨论和会议等。</li><li>以下是一些值得关注的贡献者： <ul><li>Devansh（Google Summer of Code 实习生）</li><li>Corey Snyder</li><li>Marcus</li><li>Jason Dillerman</li><li>Ali</li><li>Casey</li><li>Krunal</li><li>Zach Dover</li><li>Zach Straw Troop</li></ul></li></ul><h2 id="_5-下一季度的展望和计划" tabindex="-1">5. 下一季度的展望和计划 <a class="header-anchor" href="#_5-下一季度的展望和计划" aria-label="Permalink to &quot;5. 下一季度的展望和计划&quot;">​</a></h2><h3 id="_5-1-ceph-rgw-refactoring-meeting-2023-08-16" tabindex="-1">5.1 Ceph RGW Refactoring Meeting 2023-08-16 <a class="header-anchor" href="#_5-1-ceph-rgw-refactoring-meeting-2023-08-16" aria-label="Permalink to &quot;5.1 Ceph RGW Refactoring Meeting 2023-08-16&quot;">​</a></h3><ul><li>继续完善下一代 Pulpito 的功能。</li><li>探索将常用命令存储在数据库中的可能性。</li><li>增强错误日志的展示方式，提供更结构化的错误信息。</li></ul><h3 id="_5-2-cds-squid-nvme-of-gateway" tabindex="-1">5.2 CDS Squid: NVMe-oF-Gateway <a class="header-anchor" href="#_5-2-cds-squid-nvme-of-gateway" aria-label="Permalink to &quot;5.2 CDS Squid: NVMe-oF-Gateway&quot;">​</a></h3><ul><li>继续研究如何实现更智能的负载均衡机制。</li><li>完善配置选项，允许用户更灵活地配置路径状态。</li><li>进行更多的测试，确保在各种故障情况下客户端能够正确地重新连接。</li></ul><h3 id="_5-3-ceph-orchestrator-meeting-2023-08-29" tabindex="-1">5.3 Ceph Orchestrator Meeting 2023-08-29 <a class="header-anchor" href="#_5-3-ceph-orchestrator-meeting-2023-08-29" aria-label="Permalink to &quot;5.3 Ceph Orchestrator Meeting 2023-08-29&quot;">​</a></h3><ul><li><p>实施命名和目录结构变更。</p></li><li><p>在后续 PR 中将 Python Black 集成到 CI 流程中。</p></li><li><p>Ceph 社区将继续致力于改进和优化 Ceph 技术，并推动其持续发展。</p></li></ul>',27)])])}const _=a(t,[["render",o]]);export{p as __pageData,_ as default};
